def test_format_header(self):
    mt = hl.import_vcf(resource('sample2.vcf'))
    metadata = hl.get_vcf_metadata(resource('sample2.vcf'))
    f = new_temp_file(extension='vcf')
    hl.export_vcf(mt, f, metadata=metadata)
    s = set()
    with hl.current_backend().fs.open(f, 'r') as i:
        for line in i:
            if line.startswith('##FORMAT'):
                s.add(line.strip())
    assert s == {'##FORMAT=<ID=GT,Number=1,Type=String,Description="Genotype">', '##FORMAT=<ID=AD,Number=R,Type=Integer,Description="Allelic depths for the ref and alt alleles in the order listed">', '##FORMAT=<ID=DP,Number=1,Type=Integer,Description="Read Depth">', '##FORMAT=<ID=GQ,Number=1,Type=Integer,Description="Genotype Quality">', '##FORMAT=<ID=PL,Number=G,Type=Integer,Description="Normalized, Phred-scaled likelihoods for genotypes as defined in the VCF specification">'}

